// A API responde { success, data: [...], meta }. O n8n recebe isso como UM
// item so. Aqui a lista vira N itens, para o loop poder iterar ticket a ticket.
const body = $input.first().json;
const tickets = Array.isArray(body.data) ? body.data : [];
return tickets.map(t => ({ json: t }));

const cfg = $('Config').first().json;
const ticket = $('Loop tickets').first().json;

// So categorias ATIVAS entram. A API aceita categoria desativada em ticket
// antigo, mas nao em ticket novo - sugerir uma delas geraria erro 400.
const cats = ($('Categorias').first().json.data || [])
  .filter(c => c.is_active === undefined || c.is_active === true || Number(c.is_active) === 1);

const listaCats = cats.map(c => c.id + ' = ' + c.name).join('\n');

// PROMPT v3 - rubrica de ATENDIMENTO AO CLIENTE.
//
// A v2 usava criterios de suporte interno de TI ("quantas pessoas param de
// trabalhar", "existe contorno"). Rodando em dados reais isso quebrou: as
// categorias deste helpdesk sao Pagamento, Entrega, Produto, Garantia, Conta -
// é atendimento a cliente, nao TI interna. Um cliente cobrado duas vezes no
// cartao nao "para de trabalhar", entao a rubrica antiga o jogava em BAIXA,
// quando é provavelmente o chamado mais urgente da fila.
//
// O eixo certo aqui e: dinheiro do cliente, prazo legal/contratual, e quantos
// clientes foram atingidos.
//
// Os tres mecanismos que fazem funcionar continuam os mesmos:
//   1. RUBRICA com criterio objetivo, nao adjetivos.
//   2. CALIBRACAO dizendo que URGENTE e raro - sem isso o modelo marca tudo.
//   3. ORDEM DOS CAMPOS: sinais e impacto ANTES de priority. O modelo gera
//      token a token, entao a decisao sai do raciocinio ja escrito.
const prompt = [
  'Voce classifica chamados de ATENDIMENTO AO CLIENTE. Responda APENAS com JSON valido.',
  '',
  'CATEGORIAS (use exatamente um destes ids, nunca invente):',
  listaCats,
  '',
  'RUBRICA DE PRIORIDADE - siga a letra:',
  'BAIXA   = duvida, pedido de informacao ou solicitacao sem prazo. Nada de dinheiro em risco.',
  'MEDIA   = problema real, mas com contorno ou solucao simples. Insatisfacao sem perda financeira.',
  'ALTA    = dinheiro de UM cliente em risco, OU ele pagou e nao recebeu, OU ha prazo contratual proximo.',
  'URGENTE = VARIOS clientes atingidos pelo mesmo problema, OU dano irreversivel, OU prazo legal vencendo (PROCON, direito de arrependimento).',
  '',
  'CALIBRACAO: a maioria dos chamados e MEDIA ou BAIXA. URGENTE e raro - menos de 1 em 20.',
  'Urgencia declarada pelo cliente NAO e criterio: julgue pelo impacto descrito.',
  'Nao rebaixe um chamado so porque atinge uma pessoa so - dinheiro de um cliente ja e ALTA.',
  '',
  'EXEMPLOS:',
  "'Queria saber se meu produto ainda tem garantia' -> BAIXA",
  "'Como altero o endereco de entrega do meu cadastro' -> BAIXA",
  "'O produto veio com um risco na lateral, mas funciona' -> MEDIA",
  "'A entrega atrasou dois dias e ninguem me avisou' -> MEDIA",
  "'Fui cobrado duas vezes no cartao pelo mesmo pedido' -> ALTA",
  "'Paguei ha uma semana e o pedido nao aparece no sistema' -> ALTA",
  "'Varios clientes estao relatando cobranca duplicada hoje' -> URGENTE",
  "'O prazo do PROCON para responder vence amanha' -> URGENTE",
  '',
  'CHAMADO:',
  'Titulo: ' + ticket.title,
  'Descricao: ' + ticket.description,
  '',
  'Responda nesta ordem exata de campos (o raciocinio vem ANTES da decisao):',
  '{"sinais": ["<fato observado no texto>"], "impacto": "<quantos clientes, ha dinheiro em risco, ha prazo>", "priority": "<BAIXA|MEDIA|ALTA|URGENTE>", "categoryId": <numero>, "resumo": "<1 a 2 linhas>"}'
].join('\n');

return [{ json: { prompt, ticketId: ticket.id } }];

// PORTAO DE SEGURANCA. O modelo pode alucinar um id de categoria, inventar
// prioridade ou devolver texto solto. Nada disso pode chegar na API.
//
// MEDIDO em 26/08/2026, 4 chamados de gravidades diferentes:
//   qwen2.5:3b -> 0 de 4 na prioridade. Marcou tudo como URGENTE, inclusive
//                 "esqueci a senha, sem pressa". Modelo pequeno demais.
//   qwen2.5:7b -> 4 de 4, com a rubrica do node anterior. 3,7s por chamado.
// Nao ha campo de confianca: o modelo respondia 0.9 em tudo, inclusive nos
// erros. Auto-avaliacao de confianca nao serve como portao - o schema serve.
const cfg = $('Config').first().json;
const ticket = $('Loop tickets').first().json;
const cats = $('Categorias').first().json.data || [];
const idsValidos = cats.map(c => Number(c.id));
const PRIORIDADES = ['BAIXA', 'MEDIA', 'ALTA', 'URGENTE'];

let r = null;
try { r = JSON.parse($json.response); } catch (e) { r = null; }

const problemas = [];
if (!r || typeof r !== 'object') {
  problemas.push('o modelo nao devolveu JSON valido');
} else {
  if (!idsValidos.includes(Number(r.categoryId))) {
    problemas.push('categoryId ' + r.categoryId + ' nao existe');
  }
  if (!PRIORIDADES.includes(String(r.priority).toUpperCase())) {
    problemas.push('prioridade invalida: ' + r.priority);
  }
}

const ok = problemas.length === 0;
const prioridade = ok ? String(r.priority).toUpperCase() : null;
const cat = ok ? cats.find(c => Number(c.id) === Number(r.categoryId)) : null;

// A nota vai como INTERNA. Ver regra 20 do message.service: mensagem PUBLICA
// de staff em ticket ABERTO sem dono faz o autor ASSUMIR o ticket - o bot
// viraria responsavel e o chamado sumiria da fila humana, sem erro nenhum.
const nota = ok
  ? [
      cfg.marcador + ' classificacao automatica',
      'Categoria: ' + cat.name + ' (#' + r.categoryId + ')',
      'Prioridade: ' + prioridade,
      'Impacto avaliado: ' + (r.impacto || '-'),
      'Sinais: ' + (Array.isArray(r.sinais) ? r.sinais.join(', ') : '-'),
      '',
      'Resumo: ' + (r.resumo || '-'),
      '',
      'Gerado por ' + cfg.modelo + ' rodando local. Nenhum atendente foi atribuido',
      'de proposito: use Assumir.'
    ].join('\n')
  : [
      cfg.marcador + ' NAO consegui classificar com seguranca',
      'Motivo: ' + problemas.join('; '),
      '',
      'O ticket foi deixado na fila SEM alteracao. Precisa de triagem humana.'
    ].join('\n');

const cores = { URGENTE: 15158332, ALTA: 15105570, MEDIA: 3447003, BAIXA: 9807270 };

return [{ json: {
  ok,
  ticketId: ticket.id,
  titulo: ticket.title,
  cliente: (ticket.client || {}).name || '-',
  categoryId: ok ? Number(r.categoryId) : null,
  categoria: ok ? cat.name : null,
  priority: prioridade,
  impacto: r ? r.impacto : null,
  resumo: r ? r.resumo : null,
  problemas: problemas.join('; '),
  nota,
  cor: ok ? (cores[prioridade] || 3447003) : 10070709
} }];
